// js/state.js — every other module imports `state` and reads/writes
// its properties (legal); only this module could reassign `state` itself
// (never needs to — the object identity never changes).
export const state = {
  allEvidence: [],
  filteredEvidence: [],
  selectedEvidence: null,
  bookmarks: [],
  currentPage: "dashboard",

  allPeople: [],
  allLocations: [],
  allTimeline: [],
  caseData: {},

  currentPeopleTab: "people",
  loadingStepsRemaining: 2,

  evidenceViewLoading: true,

  viewRendered: {
    dashboard: false,
    evidence: false,
    people: false,
    timeline: false,
    workspace: false
  },

  notesStore: {},
  modalCloseListenerCount: 0
};

// Pure constants, never reassigned anywhere — plain named exports rather
// than state properties, since nothing treats them as mutable.
export const STORAGE_KEY_BOOKMARKS = "remotion_bookmarks";
export const STORAGE_KEY_NOTES = "remotion_notes";
export const STORAGE_KEY_HYPOTHESIS = "remotion_hypothesis";

// Functions reached only through inline HTML attributes (onclick="...",
// onchange="...", or the onchange string set via setAttribute below) must
// exist as globals — inline handler attributes are evaluated in the global
// scope, not in this module's scope.
window.navigateTo = navigateTo;
window.switchPeopleTab = switchPeopleTab;
window.handleSortChange = handleSortChange;
window.saveHypothesis = saveHypothesis;
window.closeEvidenceDetail = closeEvidenceDetail;
window.saveCurrentNote = saveCurrentNote;
window.renderEvidenceList = renderEvidenceList; // needed by the setAttribute("onchange", ...) below

// All are exported as named exports — there are seven equally-weighted
// utilities here, with no single "primary" one that would justify a
// default export.
import { state } from "./state.js";

export function findEvidenceById(id) {
  for (var i = 0; i < state.allEvidence.length; i++) {
    if (state.allEvidence[i].id === id) return state.allEvidence[i];
  }
  return null;
}

export function findPersonById(id) {
  for (var i = 0; i < state.allPeople.length; i++) {
    if (state.allPeople[i].id === id) return state.allPeople[i];
  }
  return null;
}

export function findLocationById(id) {
  for (var i = 0; i < state.allLocations.length; i++) {
    if (state.allLocations[i].id === id) return state.allLocations[i];
  }
  return null;
}

// Only `loadAllData` is ever called from outside this module (main.js's
// initApp) — every other function here is an internal step of that one
// loading sequence. One real "public" thing to offer justifies a default
// export rather than a named one; everything else stays unexported.

// ... loadCorePeopleAndLocations / loadEvidenceData / loadTimelineData /
// showLoadingOverlay / hideLoadingStep — all module-private, omitted here ...

export default function loadAllData() {
  showLoadingOverlay("Loading case file…");
  state.loadingStepsRemaining = 2;
  return loadCorePeopleAndLocations().then(function () {
    loadEvidenceData();
    loadTimelineData();
  });
}

function loadEvidenceData() {
  fetch("data/evidence.json")
    .then(function (res) {
      return res.json();
    })
    .then(function (data) {
      state.allEvidence = data;
      applyStoredBookmarkFlags();
      state.filteredEvidence = state.allEvidence;
      renderDashboard();
      populateAllDropdowns();
      if (state.currentPage === "evidence") renderEvidenceList();
    })
    .catch(function (err) {
      console.error("Failed to load evidence.json", err);
      alert("Evidence could not be loaded. Some views may be incomplete.");
    });
}
